"""The public branch keeps no per-row split file: the manifest is regenerated by seed and checked against one whole hash."""
import json
import subprocess

import pandas as pd
import pytest

from lotte_audit import paths, splits


def test_no_per_row_manifest_is_tracked():
    tracked = subprocess.run(["git", "-C", str(paths.ROOT), "ls-files", "manifests"], capture_output=True, text=True).stdout.splitlines()
    assert "manifests/splits_seed42.csv" not in tracked
    assert not (paths.MANIFESTS / "splits_seed42.csv").exists()


def test_no_commit_of_this_branch_holds_the_manifest_file():
    objects = subprocess.run(["git", "-C", str(paths.ROOT), "rev-list", "HEAD", "--objects"], capture_output=True, text=True).stdout
    assert "splits_seed42.csv" not in objects


def test_summary_holds_a_whole_hash_and_no_rows():
    meta = json.loads(paths.SPLIT_META.read_text(encoding="utf-8"))
    assert len(meta["manifest_sha256"]) == 64
    assert meta["seed"] == paths.SEED and sum(meta["rows"].values()) == 5874


def test_the_hash_is_on_the_whole_text():
    a = pd.DataFrame({"row_index": [0, 1], "row_hash": ["aa", "bb"], "split": ["train", "test"]})
    b = pd.DataFrame({"row_index": [0, 1], "row_hash": ["aa", "bb"], "split": ["train", "train"]})
    assert splits.manifest_sha256(a) != splits.manifest_sha256(b)
    assert splits.manifest_sha256(a) == splits.manifest_sha256(a.copy())


def test_regeneration_matches_the_hash_and_the_summary(real):
    manifest = splits.load_manifest(real["df"])
    meta = json.loads(paths.SPLIT_META.read_text(encoding="utf-8"))
    assert splits.manifest_sha256(manifest) == meta["manifest_sha256"]
    assert manifest.split.value_counts().to_dict() == meta["rows"]


def test_a_changed_row_or_hash_stops_loading(real, tmp_path, monkeypatch):
    with pytest.raises(ValueError, match="hash"):
        splits.load_manifest(real["df"].iloc[::-1].reset_index(drop=True))
    meta = json.loads(paths.SPLIT_META.read_text(encoding="utf-8"))
    meta["manifest_sha256"] = "0" * 64
    other = tmp_path / "meta.json"
    other.write_text(json.dumps(meta), encoding="utf-8")
    monkeypatch.setattr(paths, "SPLIT_META", other)
    with pytest.raises(ValueError, match="hash"):
        splits.load_manifest(real["df"])
